const payload = $workflow.input.updatePayload || {};
const summary = payload.summaryPatch || {};
const details = payload.payload || {};
const contextResponse = $context.outputs.http_request_context || {};
const readJson = (response) => {
  let content = response.content ?? response.body ?? null;
  if (typeof content === 'string') {
    try { content = JSON.parse(content); } catch (_) {}
  }
  if (content && typeof content === 'object') return content;
  if (response.rawStringBody) {
    try { return JSON.parse(response.rawStringBody); } catch (_) { return { rawStringBody: response.rawStringBody }; }
  }
  return {};
};
const contextEnvelope = readJson(contextResponse);
const caseContext = contextEnvelope.data || contextEnvelope || {};
const dispute = caseContext.dispute || {};
const events = Array.isArray(caseContext.events) ? caseContext.events : [];
const evidence = Array.isArray(caseContext.evidence) ? caseContext.evidence : [];
const decisions = Array.isArray(caseContext.decisions) ? caseContext.decisions : [];
const stage = payload.stage || summary.currentStage || dispute.currentStage || 'Case update';
const status = payload.status || summary.status || dispute.status || 'completed';
const eventType = payload.eventType || 'case.updated';
const disputeId = payload.externalDisputeId || dispute.externalDisputeId || 'demo';
const caseKey = payload.externalCaseKey || dispute.externalCaseKey || ('LoanShieldDemoPortal:' + disputeId);
const title = payload.title || (stage + ' update');
const actor = payload.actorName || 'LoanShield Maestro';
const source = payload.source || 'UiPath Maestro Case';
const correlationId = payload.correlationId || 'n/a';
const eventId = payload.eventId || 'n/a';
const portalClosed = dispute.status === 'closed' || dispute.currentStage === 'Closure' || payload.eventType === 'case.closed';
const effectiveStage = portalClosed ? 'Closure' : stage;
const effectiveStatus = portalClosed ? 'completed' : status;
const effectiveEventType = portalClosed ? 'case.closed' : eventType;
const portalUrl = 'https://agenthack-loandispute.vercel.app/disputes/' + encodeURIComponent(disputeId);
const esc = (v) => String(v ?? '').replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));
const jsonPreview = (obj, limit = 4000) => { let text = ''; try { text = JSON.stringify(obj || {}, null, 2); } catch (_) { text = String(obj || ''); } return text.length > limit ? text.slice(0, limit) + '\n... truncated ...' : text; };
const money = (v, currency = dispute.currency || details.currency || 'USD') => (v === undefined || v === null || v === '') ? '' : new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(Number(v));
const when = (v) => { if (!v) return ''; const d = new Date(v); return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleString('en-US', { timeZone: 'America/Chicago', dateStyle: 'medium', timeStyle: 'short' }) + ' CT'; };
const row = (label, value) => (value !== undefined && value !== null && value !== '') ? '<tr><td style="padding:9px 12px;color:#475569;font-weight:700;border-bottom:1px solid #e2e8f0;width:34%;">' + esc(label) + '</td><td style="padding:9px 12px;color:#0f172a;border-bottom:1px solid #e2e8f0;">' + esc(value) + '</td></tr>' : '';
const section = (heading, inner) => '<div style="margin-top:22px;"><h2 style="font-size:17px;line-height:1.25;margin:0 0 10px;color:#0f172a;">' + esc(heading) + '</h2>' + inner + '</div>';
const card = (inner) => '<div style="border:1px solid #dbe5ef;border-radius:8px;background:#ffffff;overflow:hidden;">' + inner + '</div>';
const table = (rows) => '<table role="presentation" cellspacing="0" cellpadding="0" style="width:100%;border-collapse:collapse;">' + rows + '</table>';
const firstPortalEvent = events.slice().reverse().find((e) => e.eventType === 'portal.dispute.created') || {};
const triggerInfo = (firstPortalEvent.payload && (firstPortalEvent.payload.input || firstPortalEvent.payload.trigger || firstPortalEvent.payload)) || details.trigger || details.webhook || details || {};
const triggerRows = row('Trigger event type', triggerInfo.eventType || dispute.eventType || eventType) + row('Scenario', triggerInfo.scenarioKey) + row('Customer', triggerInfo.customerName || dispute.customerName) + row('Customer segment', triggerInfo.customerSegment || dispute.customerSegment) + row('Loan type', triggerInfo.loanType || dispute.loanType) + row('Loan ID', triggerInfo.loanIdMasked || dispute.loanIdMasked) + row('Transaction ID', triggerInfo.transactionId || dispute.transactionId) + row('Dispute type', triggerInfo.disputeType || dispute.disputeType) + row('Disputed amount', money(triggerInfo.disputedAmount ?? dispute.disputedAmount)) + row('Priority', triggerInfo.priority || dispute.priority) + row('Evidence supplied', triggerInfo.hasEvidence === true ? 'Yes' : triggerInfo.hasEvidence === false ? 'No' : '') + row('Narrative', triggerInfo.narrative || dispute.narrative);
const order = ['Webhook Intake', 'Loan Context', 'Policy Triage', 'Evidence Collection', 'Investigation', 'Human Decision', 'Settlement', 'Closure'];
const norm = (s) => { const text = String(s || '').toLowerCase(); if (text.includes('context')) return 'Loan Context'; if (text.includes('policy') || text.includes('triage')) return 'Policy Triage'; if (text.includes('evidence')) return 'Evidence Collection'; if (text.includes('investigation') || text.includes('fraud') || text.includes('servicing')) return 'Investigation'; if (text.includes('decision') || text.includes('human')) return 'Human Decision'; if (text.includes('settlement') || text.includes('correction')) return 'Settlement'; if (text.includes('closure') || text.includes('communication')) return 'Closure'; if (text.includes('intake') || text.includes('webhook') || text.includes('demo')) return 'Webhook Intake'; return s || 'Update'; };
const stageDescriptions = { 'Webhook Intake': 'Webhook payload was received, authenticated, and correlated to the external LoanShield dispute.', 'Loan Context': 'Loan and customer context were retrieved so the case could be evaluated against the correct account and transaction.', 'Policy Triage': 'Policy triage classified the dispute path and selected the servicing correction route for the duplicate autopay scenario.', 'Evidence Collection': 'Evidence was checked for sufficiency, including statement or receipt support for the duplicate debit claim.', 'Investigation': 'Servicing and fraud checks were completed to rule out fraud hold handling and confirm the payment correction path.', 'Human Decision': 'The decision step approved the customer remediation path and allowed settlement to proceed.', 'Settlement': 'The correction and settlement step posted the clearing action for the disputed debit.', 'Closure': 'Closure communication and audit QA completed; the portal case is marked closed.' };
const orderedEvents = events.slice().sort((a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0));
const latestByStage = new Map();
for (const e of orderedEvents) latestByStage.set(norm(e.stage || e.title || e.eventType), e);
const stageTimeline = order.map((name) => ({ name, event: latestByStage.get(name) })).filter((item) => item.event);
const timelineRows = stageTimeline.map(({ name, event }) => '<tr><td style="padding:10px 12px;border-bottom:1px solid #e2e8f0;vertical-align:top;"><div style="font-weight:700;color:#0f172a;">' + esc(name) + '</div><div style="font-size:12px;color:#64748b;margin-top:2px;">' + esc(when(event.createdAt)) + '</div></td><td style="padding:10px 12px;border-bottom:1px solid #e2e8f0;vertical-align:top;"><div style="font-weight:700;color:#166534;">' + esc(event.status || 'completed') + '</div><div style="font-size:13px;color:#475569;margin-top:3px;">' + esc(stageDescriptions[name] || event.description || event.title || event.eventType) + '</div></td></tr>').join('');
const evidenceHtml = evidence.length ? evidence.slice(0, 5).map((item) => '<li style="margin:0 0 8px;"><strong>' + esc(item.fileName || item.documentType || item.evidenceId) + '</strong> - ' + esc(item.description || item.validationStatus || 'Evidence item recorded') + '</li>').join('') : '<li style="margin:0;">No evidence records were returned by the portal context endpoint.</li>';
const decisionHtml = decisions.length ? decisions.slice(0, 5).map((item) => '<li style="margin:0 0 8px;"><strong>' + esc(item.recommendedOutcome || item.decisionType || 'Decision') + '</strong> - ' + esc(item.decisionRationale || item.recommendationRationale || item.decidedBy || 'Decision record captured') + '</li>').join('') : '<li style="margin:0;">No separate decision records were returned; decision status is reflected in the stage timeline.</li>';
const currentRows = row('Dispute ID', disputeId) + row('External case key', caseKey) + row('Current event type', effectiveEventType) + row('Current stage', effectiveStage) + row('Current status', effectiveStatus) + row('Source', source) + row('Actor', actor) + row('Correlation ID', correlationId) + row('Event ID', eventId) + row('Portal status', dispute.status) + row('Portal current stage', dispute.currentStage) + row('Recommended outcome', summary.recommendedOutcome || details.recommendedOutcome || dispute.recommendedOutcome) + row('Final outcome', summary.finalOutcome || details.finalOutcome || dispute.finalOutcome) + row('Approved amount', money(summary.approvedAmount ?? details.approvedAmount ?? dispute.approvedAmount));
const isClosure = /closure/i.test(effectiveStage) || effectiveEventType === 'case.closed' || effectiveStatus === 'closed' || dispute.status === 'closed';
const approvedAmount = summary.approvedAmount ?? details.approvedAmount ?? dispute.approvedAmount ?? triggerInfo.disputedAmount ?? dispute.disputedAmount;
const closureCopy = isClosure ? '<p style="margin:0 0 12px;color:#334155;line-height:1.55;">The dispute has been cleared and the case is closed. The run received the original LoanShield trigger, correlated it to the portal dispute, retrieved loan context, completed policy triage, confirmed available evidence, ran investigation checks, approved the remediation path, posted the settlement/correction step, and completed closure communication.</p><p style="margin:0;color:#334155;line-height:1.55;">Clearance summary: the duplicate autopay scenario was validated against the customer narrative and supporting evidence. The transaction ' + esc(triggerInfo.transactionId || dispute.transactionId || 'n/a') + ' for ' + esc(money(triggerInfo.disputedAmount ?? dispute.disputedAmount)) + ' was handled through the servicing correction path. The approved clearing amount recorded for closure is ' + esc(money(approvedAmount)) + ', and the portal now shows status ' + esc(dispute.status || status) + ' at stage ' + esc(dispute.currentStage || effectiveStage) + '.</p>' : '<p style="margin:0;color:#334155;line-height:1.55;">This is an in-flight stage notification. The sections below show the trigger/update received by UiPath and the stage history available so far.</p>';
const subject = isClosure ? 'LoanShield Closure Cleared: ' + disputeId : 'LoanShield ' + effectiveStage + ': ' + effectiveStatus + ' - ' + disputeId;
const body = '<!doctype html><html><body style="margin:0;background:#f4f7fb;font-family:Arial,Helvetica,sans-serif;color:#0f172a;"><div style="max-width:760px;margin:0 auto;padding:24px;"><div style="background:#ffffff;border:1px solid #dbe5ef;border-radius:8px;overflow:hidden;"><div style="background:#0f766e;color:white;padding:22px 24px;"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;opacity:.85;">LoanShield Maestro case notification</div><h1 style="margin:8px 0 0;font-size:24px;line-height:1.25;">' + esc(title) + '</h1><p style="margin:8px 0 0;color:#d9fffb;font-size:14px;">' + esc(dispute.customerName || triggerInfo.customerName || 'LoanShield customer') + ' | ' + esc(disputeId) + '</p></div><div style="padding:22px 24px;">' + section(isClosure ? 'Detailed Closure Summary' : 'Stage Summary', closureCopy) + section('Current UiPath Update', card(table(currentRows))) + section('Original Trigger Information', card(table(triggerRows) + '<div style="padding:12px;background:#f8fafc;border-top:1px solid #e2e8f0;"><div style="font-size:12px;font-weight:700;color:#475569;margin-bottom:6px;">Raw trigger/update payload</div><pre style="white-space:pre-wrap;margin:0;font-size:12px;line-height:1.45;color:#0f172a;">' + esc(jsonPreview({ originalPortalTrigger: triggerInfo, currentUiPathUpdate: payload })) + '</pre></div>')) + section('Previous Case Stages', card(table(timelineRows || row('Stage history', 'No prior stage events returned yet')))) + section('Evidence and Decisions', '<div style="display:block;border:1px solid #dbe5ef;border-radius:8px;background:#ffffff;padding:14px 16px;"><h3 style="font-size:14px;margin:0 0 8px;color:#0f172a;">Evidence</h3><ul style="margin:0 0 14px 18px;padding:0;color:#334155;line-height:1.45;">' + evidenceHtml + '</ul><h3 style="font-size:14px;margin:0 0 8px;color:#0f172a;">Decision trail</h3><ul style="margin:0 0 0 18px;padding:0;color:#334155;line-height:1.45;">' + decisionHtml + '</ul></div>') + '<p style="margin:20px 0 0;font-size:14px;line-height:1.5;color:#475569;">Dashboard: <a href="' + portalUrl + '" style="color:#0f766e;font-weight:700;text-decoration:none;">' + esc(portalUrl) + '</a></p></div><div style="background:#f8fafc;border-top:1px solid #e2e8f0;padding:14px 24px;color:#64748b;font-size:12px;line-height:1.45;">Generated by UiPath Integration Service Gmail activity from the LoanShield Maestro case workflow after posting the portal callback and reading case context.</div></div></div></body></html>';
return { subject, body, stage: effectiveStage, status: effectiveStatus, disputeId, eventType: effectiveEventType, portalUrl, contextEventCount: events.length, evidenceCount: evidence.length, decisionCount: decisions.length };
